    return { nav: '', title: 'KipuControl · ERP y CRM para agencias de viaje y tour operadores', desc: 'Cotiza en minutos, controla cupos, cobra con Yape, tarjeta o PayPal y lanza tu web con SEO. Prueba 14 días gratis, sin tarjeta.', html, exit: 'POP-01',
      ld: { '@context': 'https://schema.org', '@graph': [{ '@type': 'Organization', name: 'KipuControl', url: 'https://' + L().domain, logo: 'https://' + L().domain + '/logo.png' }, { '@type': 'SoftwareApplication', name: 'KipuControl', applicationCategory: 'BusinessApplication', operatingSystem: 'Web, iOS, Android', aggregateRating: { '@type': 'AggregateRating', ratingValue: 4.9, reviewCount: 312 }, offers: PLANS.filter(p => planPrice(p) > 0).map(p => ({ '@type': 'Offer', name: p, price: planPrice(p), priceCurrency: 'PEN' })) }, { '@type': 'FAQPage', mainEntity: L().faq.map(([q, a]) => ({ '@type': 'Question', name: q, acceptedAnswer: { '@type': 'Answer', text: a } })) }] },
      after: (el) => {
        bindPlans(el, '#kc-pl', st);
        el.querySelectorAll('[data-scroll]').forEach(a => a.onclick = (e) => { e.preventDefault(); el.querySelector('#' + a.dataset.scroll).scrollIntoView({ behavior: 'smooth' }); });
        el.querySelectorAll('#kc-hc button').forEach(b => b.onclick = () => { el.querySelectorAll('#kc-hc button').forEach(x => x.classList.toggle('on', x === b)); const rows = L().posts.filter(p => p.status === 'publicado' && (!b.dataset.c || p.category === b.dataset.c)).slice(0, 3); el.querySelector('#kc-hp').innerHTML = rows.length ? rows.map(pcard).join('') : UI.empty('Pronto publicaremos artículos de esta categoría.', 'file'); });
      } };
