        el.querySelector('#kc-copy').onclick = () => { try { const w = navigator.clipboard && navigator.clipboard.writeText(url); if (w && w.catch) w.catch(() => {}); } catch (e) { /* sin portapapeles */ } UI.toast('Enlace copiado: ' + url, 'ok'); };
        el.querySelectorAll('[data-vote]').forEach(b => b.onclick = () => { UI.toast(b.dataset.vote === '1' ? '¡Gracias! Nos ayuda a escribir mejores guías.' : 'Gracias. Cuéntanos en los comentarios qué faltó.', 'ok'); el.querySelectorAll('[data-vote]').forEach(x => x.disabled = true); });
